// Parse real LHA archives produced by actual Amiga and DOS tools.
//
// These are genuine files, not fixtures I built: they come from the lhasa
// project's regression corpus (ISC licensed), generated by LhA v1.22 and v2.12
// on AmigaOS plus various DOS tools. That matters because the hand-built
// fixtures in the other LHA tests can only confirm the parser agrees with my
// own understanding of the format. These confirm it agrees with the tools that
// actually write archives in the wild.
//
// Every archive here is verified by CRC-16, so a passing test means the
// decompressors reproduced the original bytes exactly.

import { describe, it, expect } from 'vitest'
import { readFileSync } from 'node:fs'
import { resolve } from 'node:path'
import { parseLha } from './lha'
import { parseHeaders } from './lhaHeader'
import { crc16 } from './lhaCrc'

const DIR = resolve(__dirname, '../testFixtures/lha')

/** Read a fixture as raw bytes. */
function load(name: string): Uint8Array {
  return new Uint8Array(readFileSync(resolve(DIR, name)))
}

/** Parse and assert the archive's own CRC agrees with the decompressed data. */
function parseVerified(name: string) {
  const archive = parseLha(load(name))
  expect(archive.entries.length, `${name} entries`).toBeGreaterThan(0)
  for (const entry of archive.entries) {
    expect(entry.data.length, `${name} ${entry.filename} size`)
      .toBe(entry.uncompressedSize)
    // crc 0 means the writer recorded none
    if (entry.crc !== 0) {
      expect(crc16(entry.data), `${name} ${entry.filename} CRC`).toBe(entry.crc)
    }
  }
  return archive
}

describe('real archives: compression methods', () => {
  // LhA v1.22 on AmigaOS, each holding the same 18092-byte text file
  it('reads -lh0- (stored) and reproduces the exact bytes', () => {
    const archive = parseVerified('lh0.lzh')
    expect(archive.entries[0].method).toBe('-lh0-')
    // This archive holds a gzipped licence text, not the plain file the
    // compressed archives carry
    expect(archive.entries[0].data.length).toBe(6829)
    expect(archive.entries[0].filename).toBe('gpl-2.gz')
  })

  it('reads -lh1- (LZSS + dynamic Huffman)', () => {
    const archive = parseVerified('lh1.lzh')
    expect(archive.entries[0].method).toBe('-lh1-')
    expect(archive.entries[0].data.length).toBe(18092)
  })

  it('reads -lh4- (LZSS + static Huffman, 12-bit dictionary)', () => {
    const archive = parseVerified('lh4.lzh')
    expect(archive.entries[0].method).toBe('-lh4-')
  })

  it('reads -lh5- (13-bit dictionary)', () => {
    const archive = parseVerified('lh5.lzh')
    expect(archive.entries[0].method).toBe('-lh5-')
  })

  it('reads -lh6- (15-bit dictionary)', () => {
    const archive = parseVerified('lh6.lzh')
    expect(archive.entries[0].method).toBe('-lh6-')
  })

  it('produces identical output from every method for the same source file', () => {
    // lh1/lh4/lh5/lh6 all hold the same 18092-byte file, so their decompressed
    // bytes must match each other. This is the strongest check available: it
    // compares four independent decompressors against one another.
    // (lh0.lzh holds a different, smaller file, so it is excluded.)
    const reference = parseLha(load('lh1.lzh')).entries[0].data
    expect(reference.length).toBe(18092)
    for (const name of ['lh4.lzh', 'lh5.lzh', 'lh6.lzh']) {
      const other = parseLha(load(name)).entries[0].data
      expect(other.length, name).toBe(reference.length)
      expect(Buffer.from(other).equals(Buffer.from(reference)), name).toBe(true)
    }
  })
})

describe('real archives: header levels', () => {
  it('reads a level 0 header', () => {
    expect(parseHeaders(load('level0.lzh'))[0].headerLevel).toBe(0)
  })

  it('reads level 1 headers from both Amiga tool versions', () => {
    expect(parseHeaders(load('level1-amiga122.lzh'))[0].headerLevel).toBe(1)
    expect(parseHeaders(load('level1-amiga212.lzh'))[0].headerLevel).toBe(1)
  })

  it('reads level 2 headers from both Amiga tool versions', () => {
    expect(parseHeaders(load('level2-amiga122.lzh'))[0].headerLevel).toBe(2)
    expect(parseHeaders(load('level2-amiga212.lzh'))[0].headerLevel).toBe(2)
  })

  it('recovers the same path from every header level and tool', () => {
    const names = [
      'level0.lzh', 'level1-amiga122.lzh', 'level1-amiga212.lzh',
      'level2-amiga122.lzh', 'level2-amiga212.lzh',
    ]
    for (const name of names) {
      const e = parseLha(load(name)).entries[0]
      // All of them describe the same nested file; separators vary by OS
      expect((e.directory + e.filename).replace(/[\\:]/g, '/'), name)
        .toBe('subdir/subdir2/hello.txt')
    }
  })

  it('reads the AmigaOS v2.12 archives too', () => {
    const archive = parseVerified('lh6.lzh')
    expect(archive.entries.length).toBeGreaterThan(0)
  })
})

describe('real archives: directory entries', () => {
  it('reconstructs a nested path from a subdirectory archive', () => {
    const entry = parseLha(load('subdir.lzh')).entries[0]
    expect(entry.directory + entry.filename).toBe('subdir/subdir2/hello.txt')
    expect(entry.data.length).toBe(12)
  })

  it('reads the file contents of a subdirectory archive', () => {
    const entry = parseLha(load('subdir.lzh')).entries[0]
    expect(new TextDecoder().decode(entry.data)).toContain('hello')
  })
})

describe('real archives: edge-case sizes', () => {
  it('handles a -lh1- archive whose file is empty', () => {
    const archive = parseVerified('lh1-0.lzh')
    expect(archive.entries[0].data.length).toBe(0)
    expect(archive.entries[0].method).toBe('-lh1-')
  })

  it('handles a one-byte file', () => {
    const archive = parseVerified('lh1-1.lzh')
    expect(archive.entries[0].data.length).toBe(1)
  })

  it('handles a -lz4- entry of zero length', () => {
    const archive = parseVerified('lz5-0.lzs')
    expect(archive.entries[0].data.length).toBe(0)
  })

  it('handles a -lz4- entry of one byte', () => {
    const archive = parseVerified('lz5-1.lzs')
    expect(archive.entries[0].data.length).toBe(1)
  })
})

describe('real archives: no internal crashes', () => {
  const files = [
    'lh0.lzh', 'lh1.lzh', 'lh4.lzh', 'lh5.lzh', 'lh6.lzh', 'subdir.lzh',
    'level0.lzh', 'level1-amiga122.lzh', 'level1-amiga212.lzh', 'level2-amiga122.lzh', 'level2-amiga212.lzh', 'lh1-0.lzh', 'lh1-1.lzh',
    'lz5-0.lzs', 'lz5-1.lzs',
  ]

  for (const name of files) {
    it(`parses ${name} without throwing`, () => {
      expect(() => parseLha(load(name))).not.toThrow()
    })
  }

  it('every archive reports a consistent header count', () => {
    for (const name of files) {
      const bytes = load(name)
      expect(parseHeaders(bytes).length, name).toBe(parseLha(bytes).entries.length)
    }
  })
})
